import json

def classify_v2(r):
    if r['execution_reward'] == 0:
        return 'not_proved'
    det = r['details']
    if 'error' in det or 'proof_failed' in det:
        return 'not_proved'
    concl = det.get('conclusion','').strip()
    components = det.get('components', [])
    concl_whole = [c['content'].strip() for c in components if c['type']=='conclusion_whole']
    concl_text = concl_whole[0] if concl_whole else concl
    premises = [c['content'].strip() for c in components if c['type']=='premise']

    # H7: any premise == conclusion (regardless of count)
    if concl_text and concl_text in premises:
        return 'H7'

    # H1: ISR=0 (all components redundant) but no premise==conclusion 
    isr = det.get('isr', r.get('sta_reward', 0))
    if isr == 0:
        return 'H1'

    return 'genuine'

